```kotlin
import org.jetbrains.kotlinx.lincheck.LoggingLevel
import org.jetbrains.kotlinx.lincheck.Options
import org.jetbrains.kotlinx.lincheck.annotations.Operation
import org.jetbrains.kotlinx.lincheck.annotations.Param
import org.jetbrains.kotlinx.lincheck.paramgen.IntGen
import org.jetbrains.kotlinx.lincheck.strategy.managed.modelchecking.ModelCheckingCTest
import org.jetbrains.kotlinx.lincheck.verifier.VerifierState

private const val KEYSPACE_SIZE = 5

@ModelCheckingCTest(verifier = VerifierState::class)
@Param.Params(
    Param(name = "key", gen = IntGen::class, conf = "1:$KEYSPACE_SIZE")
)
class NotThreadSafeTestClassLinCheckTest {
    private val notThreadSafe = NotThreadSafeTestClass()

    @Operation
    fun refreshData(@Param(name = "key") randomData: Int) {
        notThreadSafe.refreshData("key-$randomData")
    }

    @Operation
    fun getData(): Map<String, String> {
        return notThreadSafe.getData()
    }

    @Test
    fun testNotThreadSafe() {
        val options = Options.default().apply {
            iterations(100)
            threads(2)
            actorsPerThread(2)
            actorsBefore(0)
            actorsAfter(0)
            useClassPathUpdater = true
            logLevel(LoggingLevel.DEBUG)
        }
        val failure = options.checkImpl(this.javaClass)
        assert(failure != null) { "The test did not fail, which means it is thread-safe" }
    }
}
```

In the test, we generate a set of keys in this case between 1 and 5 and create LinCheck Operation methods that call `refreshData` and `getData` of our `NotThreadSafeTestClass`. The `testNotThreadSafe` test function runs LinCheck with 100 iterations to generate different interleavings, and it expects to find an issue in the test.

Running this test will likely produce a failure, which demonstrates that the code is not thread-safe.

